// Types for agent-assist.js (shared with omnirush-cli; see PARITY.sha256).
export type AgentAssistFeature = "selfCheck" | "projectNotes" | "diagnostics" | "compaction";
export type AgentAssistFlags = Record<AgentAssistFeature, boolean>;
export const FEATURES: AgentAssistFeature[];
export const FEATURES_ENV: string;
export const FEATURES_FILE_ENV: string;
export function featureFlags(input?: { env?: Record<string, string | undefined>; settings?: unknown }): AgentAssistFlags;
export function featuresEnvValue(flags: AgentAssistFlags): string;
export function featuresFromEnv(env?: Record<string, string | undefined>): AgentAssistFlags;
export const LSP_BUILTIN_IDS: string[];
export const LSP_ENABLED_IDS: string[];
export const LSP_HEAP_MB: number;
export function lspConfig(): Record<string, { disabled: true }>;
export function lspHeapMb(totalBytes?: number): number;
export function lspEngineEnv(env?: Record<string, string | undefined>, options?: { totalBytes?: number }): Record<string, string>;
export function restoreShellEnv(processEnv: Record<string, string | undefined>, output: { env?: Record<string, string> } | undefined): void;
export function filterDiagnosticsOutput(text: string): { text: string; removed: number; kept: number };
export function capDiagnosticsMetadata<T>(map: T, options?: { files?: number; per?: number }): T;
export type ProjectCheck = { kind: "typecheck" | "lint" | "test"; command: string };
export function packageManager(root: string): "pnpm" | "yarn" | "bun" | "npm";
export function detectChecks(root: string, options?: { platform?: string }): ProjectCheck[];
export function commandSegments(command: string): string[];
export function isCheckCommand(command: string, checks?: ProjectCheck[]): boolean;
export type CheckResult = { ok: boolean; passed: number | null; failed: number | null; summary: string };
export function parseCheckResult(output: string, exitCode: number | null | undefined, command?: string): CheckResult;
export function isCodeEdit(tool: string, args: unknown): boolean;
export function skipRequested(text: string): boolean;
export function declinesChange(text: string): boolean;
export const SELF_CHECK_ATTEMPTS: number;
export type CheckState = { edits: number; failures: number; ran: number; skip: boolean; last: CheckResult | null; shown: number };
export const SELF_CHECK_NOTE_REPEATS: number;
export function noteEdit(state: CheckState): void;
export function admitNote(state: CheckState, note: string | null, options?: { repeats?: number }): string | null;
export function newCheckState(): CheckState;
export function noteUserPrompt(state: CheckState, text: string): void;
export function selfCheckNote(state: CheckState, checks: ProjectCheck[], options?: { attempts?: number }): string | null;
export function noteCheckRun(state: CheckState, result: CheckResult): void;
export const NOTES_FILE: string;
export function devCommand(command: string): string | null;
export function learnedCommands(commands: string[], root: string): string[];
export function projectScan(root: string, options?: { learned?: string[] }): string;
export function droppedLines(before: string, after: string): string[];
export function notesLinesDropped(tool: string, args: unknown, root: string): { file: string; lines: string[] }[];
export function notesGuardMessage(drops: { file: string; lines: string[] }[]): string;
export type SessionLedger = { preferences: string[]; decisions: string[]; todos: string[]; worked: string[]; failing: string[]; files: string[] };
export function sessionLedger(messages: unknown[]): SessionLedger;
export function ledgerEmpty(ledger: SessionLedger | null | undefined): boolean;
export function compactionContext(ledger: SessionLedger): string;
export function missingFactsNote(ledger: SessionLedger, summary: string): string | null;
export function latestSummary(messages: unknown[]): { index: number; id: string; created: number; text: string } | null;
export const NOTICE_TITLES: string[];
